'use client';

/**
 * app-header - header with breadcrumbs or title + optional actions slot
 * Uses LayoutContext linkComponent for breadcrumb links
 */

import {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbSeparator,
  BreadcrumbPage,
} from '../ui/display/breadcrumb';
import { useLayoutContext } from './layout-context';
import { Header } from './header';

type BreadcrumbItemData = {
  label: string;
  href?: string;
  isPage?: boolean;
};

type AppHeaderProps = {
  breadcrumbs?: BreadcrumbItemData[];
  title?: string;
  fixed?: boolean;
  actions?: React.ReactNode;
};

export function AppHeader({ breadcrumbs, title, fixed = true, actions }: AppHeaderProps) {
  const { linkComponent: LinkComp } = useLayoutContext();

  return (
    <Header fixed={fixed}>
      {breadcrumbs ? (
        <Breadcrumb>
          <BreadcrumbList>
            {breadcrumbs.map((item, index) => (
              <div key={index} className="flex items-center gap-2">
                {index > 0 && <BreadcrumbSeparator />}
                <BreadcrumbItem className="text-base">
                  {item.isPage ? (
                    <BreadcrumbPage className="font-bold text-base">{item.label}</BreadcrumbPage>
                  ) : item.href ? (
                    <BreadcrumbLink asChild>
                      <LinkComp className="text-base" to={item.href}>
                        {item.label}
                      </LinkComp>
                    </BreadcrumbLink>
                  ) : (
                    <BreadcrumbLink className="text-base">{item.label}</BreadcrumbLink>
                  )}
                </BreadcrumbItem>
              </div>
            ))}
          </BreadcrumbList>
        </Breadcrumb>
      ) : title ? (
        <span className="font-bold text-base">{title}</span>
      ) : null}
      {actions && <div className="ms-auto flex items-center space-x-4">{actions}</div>}
    </Header>
  );
}

export type { BreadcrumbItemData, AppHeaderProps };

'use client';

/**
 * app-sidebar - props-driven sidebar shell
 * Accepts navGroups + optional header/footer slots. No internal data hooks.
 */

import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarRail,
} from '../ui/display/sidebar';
import { NavGroup } from './nav-group';
import { useLayoutSettings } from '../../context/layout-settings-provider';
import type { NavGroup as NavGroupType } from './types';

type AppSidebarProps = {
  navGroups: NavGroupType[];
  /** Current page href passed down for active-state detection */
  currentHref?: string;
  header?: React.ReactNode;
  footer?: React.ReactNode;
  /** Override collapsible from LayoutSettingsProvider */
  collapsible?: 'offcanvas' | 'icon' | 'none';
  /** Override variant from LayoutSettingsProvider */
  variant?: 'sidebar' | 'floating' | 'inset';
};

export function AppSidebar({
  navGroups,
  currentHref = '',
  header,
  footer,
  collapsible: collapsibleProp,
  variant: variantProp,
}: AppSidebarProps) {
  const settings = useLayoutSettings();
  const collapsible = collapsibleProp ?? settings.collapsible;
  const variant = variantProp ?? settings.variant;

  return (
    <Sidebar collapsible={collapsible} variant={variant}>
      {header && <SidebarHeader className="pb-0">{header}</SidebarHeader>}
      <SidebarContent>
        {navGroups.map((group) => (
          <NavGroup key={group.title} {...group} currentHref={currentHref} />
        ))}
      </SidebarContent>
      {footer && <SidebarFooter>{footer}</SidebarFooter>}
      <SidebarRail />
    </Sidebar>
  );
}

export type { AppSidebarProps };

'use client';

/**
 * app-title - sidebar header with logo (expanded/collapsed variants) and optional title
 * Shows `logo` when sidebar is open, `collapsedLogo` when collapsed. Logo centered.
 */

import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from '../ui/display/sidebar';
import { useLayoutContext } from './layout-context';

type AppTitleProps = {
  title?: string;
  subtitle?: string;
  homeUrl?: string;
  /** Logo shown when sidebar is expanded */
  logo?: React.ReactNode;
  /** Logo shown when sidebar is collapsed (icon variant) */
  collapsedLogo?: React.ReactNode;
};

export function AppTitle({ title, subtitle, homeUrl = '/', logo, collapsedLogo }: AppTitleProps) {
  const { setOpenMobile, state } = useSidebar();
  const { linkComponent: LinkComp } = useLayoutContext();
  const isCollapsed = state === 'collapsed';

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton
          size="lg"
          className="h-auto gap-2 py-3 hover:bg-transparent active:bg-transparent"
          asChild
        >
          <LinkComp to={homeUrl} onClick={() => setOpenMobile(false)}>
            {isCollapsed && collapsedLogo ? (
              <div className="flex w-full items-center justify-center">{collapsedLogo}</div>
            ) : (
              <>
                {logo && <div className="flex w-full items-center justify-center">{logo}</div>}
                {title && (
                  <div className="grid flex-1 text-start text-sm leading-tight">
                    <span className="truncate font-bold">{title}</span>
                    {subtitle && <span className="truncate text-xs">{subtitle}</span>}
                  </div>
                )}
              </>
            )}
          </LinkComp>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

export type { AppTitleProps };

