  [key: string]: unknown;
};

type LinkComponent = React.ComponentType<LinkComponentProps>;

/** Fallback: plain <a> tag when no router-specific link is provided */
const DefaultLink: LinkComponent = ({ to, children, ...props }) => (
  <a href={to} {...props}>
    {children}
