/**
 * nav-utils - pure utility functions for nav active state and flattening
 * No React, no router dependencies
 */

import type { NavItem, NavLink } from './types';

/**
 * Normalizes a URL by stripping trailing slash and query params
 */
function normalizeUrl(url: string): string {
  const withoutParams = url.split('?')[0] ?? url;
  return withoutParams.endsWith('/') ? withoutParams.slice(0, -1) : withoutParams;
}

/**
 * Check if a nav item (or any of its descendants) is active.
 * Compares fully-prefixed URLs against the current href directly.
 */
export function checkIsActive(href: string, item: NavItem, mainNav = false): boolean {
  const normalizedHref = normalizeUrl(href);

  // Check explicit actives array first
  if (item.actives && item.actives.length > 0) {
    const matchesActives = item.actives.some((activeUrl) => {
      const normalizedActive = normalizeUrl(activeUrl);
      return (
        normalizedHref === normalizedActive || normalizedHref.startsWith(`${normalizedActive}/`)
      );
    });
    if (matchesActives) return true;
  }

  // Recursively check child items
  if ('items' in item && item.items) {
    if (item.items.some((child) => checkIsActive(href, child))) return true;
  }

  // Check item's own URL
  if ('url' in item && item.url) {
    const normalizedItemUrl = normalizeUrl(item.url as string);

    if (mainNav && href.includes('?')) return false;

    return (
      normalizedHref === normalizedItemUrl ||
      normalizedHref.startsWith(`${normalizedItemUrl}/`) ||
      (mainNav &&
        href.split('/')[1] !== '' &&
        href.split('/')[1] === (item.url as string).split('/')[1])
    );
  }

  return false;
}

/**
 * Flatten nested nav items into a flat array with depth tracking.
 * Used by collapsed dropdown to show all leaf items.
 */
export function flattenNavItems(items: NavItem[], depth = 0): Array<NavLink & { depth: number }> {
  return items.flatMap((item) => {
    if ('items' in item && item.items) {
      return flattenNavItems(item.items, depth + 1);
    }
    return [{ ...(item as NavLink), depth }];
  });
}

/**
 * ThemeSwitch — dropdown toggle between light, dark, and system themes
 * Updates theme-color meta tag on change
 */
import { Check, Moon, Sun } from 'lucide-react';
import { useEffect } from 'react';
import { Button } from '../ui/actions/button/index';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../ui/actions/dropdown-menu/index';
import { useTheme } from '../../context/theme-provider';
import { cn } from '../../lib/utils';

export function ThemeSwitch() {
  const { theme, setTheme } = useTheme();

  /* Update theme-color meta tag when theme changes */
  useEffect(() => {
    const themeColor = theme === 'dark' ? '#020817' : '#fff';
    const metaThemeColor = document.querySelector("meta[name='theme-color']");
    if (metaThemeColor) metaThemeColor.setAttribute('content', themeColor);
  }, [theme]);

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger
        render={(props) => (
          <Button {...props} variant="ghost" size="icon" className="scale-95 rounded-full">
            <Sun className="size-[1.2rem] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
            <Moon className="absolute size-[1.2rem] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
            <span className="sr-only">Toggle theme</span>
          </Button>
        )}
      />
      <DropdownMenuContent sideOffset={20}>
        <DropdownMenuItem onClick={() => setTheme('light')}>
          Light
          <Check size={14} className={cn('ms-auto', theme !== 'light' && 'hidden')} />
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => setTheme('dark')}>
          Dark
          <Check size={14} className={cn('ms-auto', theme !== 'dark' && 'hidden')} />
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => setTheme('system')}>
          System
          <Check size={14} className={cn('ms-auto', theme !== 'system' && 'hidden')} />
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

/**
 * top-nav - horizontal nav with mobile dropdown fallback
 * Adapted from e2e-frontend: replaced TanStack Link with useLayoutContext().linkComponent
 */

import { Menu } from 'lucide-react';
import { Button } from '../ui/actions/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../ui/actions/dropdown-menu';
import { cn } from '../../lib/utils';
import { useLayoutContext } from './layout-context';

type TopNavLink = {
  title: string;
  href: string;
  isActive: boolean;
  disabled?: boolean;
};

type TopNavProps = React.HTMLAttributes<HTMLElement> & {
  links: TopNavLink[];
};

export function TopNav({ className, links, ...props }: TopNavProps) {
  const { linkComponent: LinkComp } = useLayoutContext();

  return (
    <>
      {/* Mobile: collapsed dropdown */}
      <div className="lg:hidden">
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            render={(props) => (
              <Button {...props} size="icon" variant="outline" className="md:size-7">
                <Menu />
              </Button>
            )}
          />
          <DropdownMenuContent side="bottom" align="start">
            {links.map(({ title, href, isActive, disabled }) => (
              <DropdownMenuItem
                key={`${title}-${href}`}
                disabled={disabled}
                render={(itemProps) => (
                  <LinkComp
                    {...itemProps}
                    to={href}
                    className={cn(itemProps.className, !isActive ? 'text-muted-foreground' : '')}
                  >
                    {title}
                  </LinkComp>
                )}
              />
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Desktop: inline nav links */}
      <nav
        className={cn('hidden items-center space-x-4 lg:flex lg:space-x-4 xl:space-x-6', className)}
        {...props}
      >
        {links.map(({ title, href, isActive, disabled }) => (
          <LinkComp
            key={`${title}-${href}`}
            to={href}
            aria-disabled={disabled}
            className={cn(
              'font-medium text-sm transition-colors hover:text-primary',
              !isActive && 'text-muted-foreground',
              disabled && 'pointer-events-none opacity-50'
            )}
          >
            {title}
          </LinkComp>
        ))}
      </nav>
    </>
  );
}

export type { TopNavProps, TopNavLink };

/**
 * Layout component types - router-agnostic, auth-free
 * URLs are plain strings (no TanStack Router LinkProps)
 */

type BaseNavItem = {
  title: string;
  badge?: string;
  icon?: React.ElementType;
  /** Additional URL patterns that trigger active state */
  actives?: string[];
};

type NavLink = BaseNavItem & {
  url: string;
  items?: never;
};

type NavCollapsible = BaseNavItem & {
  items: NavItem[];
  url?: never;
};

type NavItem = NavCollapsible | NavLink;

type NavGroup = {
  title: string;
  items: NavItem[];
};

type SidebarData = {
  navGroups: NavGroup[];
};

type UserData = {
  name: string;
  email: string;
  avatar?: string;
};

export type { SidebarData, NavGroup, NavItem, NavCollapsible, NavLink, UserData };
